// (40) Chek/hujjatlarni CHOP ETISH va PDF QILIB YUKLAB OLISH uchun umumiy,
// qayta ishlatiladigan modul — Sotuv (kassa), Hisobotlar, Mijozlar/Qarz va
// Ta'minotchilarga qarzim sahifalarining barchasida bir xil ishlaydi.
//
// PDF generatsiyasi uchun jsPDF kutubxonasi npm orqali EMAS, balki CDN
// orqali FAQAT KERAK BO'LGANDA (lazy) yuklanadi — shunda oddiy foydalanuvchi
// (faqat chop etadigan) uchun ilova og'irlashmaydi, va bu package.json /
// package-lock.json ga hech qanday o'zgartirish talab qilmaydi (GitHub web
// muharriri orqali qo'lda joylashda katta lockfile faylini almashtirish
// shart bo'lmaydi).

function money(n) {
  return Math.round(Number(n || 0)).toLocaleString('uz-UZ') + " so'm";
}

let jsPdfLoadPromise = null;
function loadJsPdf() {
  if (typeof window !== 'undefined' && window.jspdf && window.jspdf.jsPDF) {
    return Promise.resolve(window.jspdf.jsPDF);
  }
  if (jsPdfLoadPromise) return jsPdfLoadPromise;
  jsPdfLoadPromise = new Promise((resolve, reject) => {
    const script = document.createElement('script');
    script.src = 'https://cdn.jsdelivr.net/npm/jspdf@2.5.2/dist/jspdf.umd.min.js';
    script.onload = () => {
      if (window.jspdf && window.jspdf.jsPDF) resolve(window.jspdf.jsPDF);
      else reject(new Error("PDF kutubxonasi yuklanmadi"));
    };
    script.onerror = () => {
      jsPdfLoadPromise = null;
      reject(new Error("PDF kutubxonasini yuklab bo'lmadi — internet aloqasini tekshiring"));
    };
    document.head.appendChild(script);
  });
  return jsPdfLoadPromise;
}

// (6) Shtrix-kod (Code128/EAN-13 chizib berish) uchun JsBarcode kutubxonasi
// ham xuddi jsPDF kabi FAQAT KERAK BO'LGANDA CDN orqali yuklanadi.
let jsBarcodeLoadPromise = null;
function loadJsBarcode() {
  if (typeof window !== 'undefined' && window.JsBarcode) {
    return Promise.resolve(window.JsBarcode);
  }
  if (jsBarcodeLoadPromise) return jsBarcodeLoadPromise;
  jsBarcodeLoadPromise = new Promise((resolve, reject) => {
    const script = document.createElement('script');
    script.src = 'https://cdn.jsdelivr.net/npm/jsbarcode@3.11.6/dist/JsBarcode.all.min.js';
    script.onload = () => {
      if (window.JsBarcode) resolve(window.JsBarcode);
      else reject(new Error("Shtrix-kod kutubxonasi yuklanmadi"));
    };
    script.onerror = () => {
      jsBarcodeLoadPromise = null;
      reject(new Error("Shtrix-kod kutubxonasini yuklab bo'lmadi — internet aloqasini tekshiring"));
    };
    document.head.appendChild(script);
  });
  return jsBarcodeLoadPromise;
}

// (37/6) jsPDF'ning ichki "helvetica" shrifti faqat lotin (WinAnsi)
// belgilarini biladi — kirill harflari (masalan "Гарантия", yoki kirillcha
// mahsulot/mijoz nomlari) chiqsa, chalkash belgilar bilan ko'rinardi. Buning
// oldini olish uchun DejaVu Sans shriftining lotin+kirill harflarinigina
// o'z ichiga olgan KICHRAYTIRILGAN (subset) nusxasi bevosita shu faylga
// joylashtirilgan (CDN'dan emas — chunki bu shrift butun PDF matni uchun
// har doim zarur, ixtiyoriy emas).
const DEJAVU_SANS_REGULAR_B64 = "";
const DEJAVU_SANS_BOLD_B64 = "";

function registerPdfFonts(doc) {
  // MUHIM: shrift VFS/addFont har bir jsPDF HUJJAT NUSXASIGA (doc) alohida
  // tegishli — modul darajasidagi bitta "registered" bayrog'i ishlatilsa,
  // birinchi chek uchun ishlagan bo'lib, lekin IKKINCHI marta yaratilgan
  // yangi doc (masalan narx yorlig'i uchun) hech qanday shrift ko'rmay
  // qolar edi (sinovda aynan shu xato topildi). Shuning uchun bayroq har
  // bir doc obyektining o'zida saqlanadi.
  if (!doc.__poswayFontsRegistered) {
    doc.addFileToVFS('DejaVuSans.ttf', DEJAVU_SANS_REGULAR_B64);
    doc.addFont('DejaVuSans.ttf', 'DejaVuSans', 'normal');
    doc.addFileToVFS('DejaVuSans-Bold.ttf', DEJAVU_SANS_BOLD_B64);
    doc.addFont('DejaVuSans-Bold.ttf', 'DejaVuSans', 'bold');
    doc.__poswayFontsRegistered = true;
  }
}

function escapeHtml(s) {
  return String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
}

// data = {
//   title: string,
//   subtitleLines: string[],
//   columns: string[],
//   rows: (string|number)[][],
//   // (37) rowNotes[i] — rows[i] ostida chiqadigan kichik izoh (masalan
//   // kafolat matni); kafolatsiz qatorlar uchun shunchaki null/bo'sh
//   // qoldiriladi, hech narsa chop etilmaydi.
//   rowNotes?: (string|null)[],
//   totals: { label, value, bold?, danger? }[],
//   footerLines?: string[],
// }
export function printReceipt(data) {
  const w = window.open('', '_blank', 'width=420,height=640');
  if (!w) {
    alert("Chop etish oynasini ochib bo'lmadi — brauzeringiz popup oynalarni bloklagan bo'lishi mumkin.");
    return;
  }
  const rowNotes = data.rowNotes || [];
  const rowsHtml = (data.rows || [])
    .map((r, i) => {
      const note = rowNotes[i];
      const noteHtml = note
        ? `<tr><td colspan="${r.length}" style="border-bottom:1px solid #eee; padding:0 2px 4px; font-size:10px; color:#0033a0;">🛡️ ${escapeHtml(note)}</td></tr>`
        : '';
      return `<tr>${r
        .map((c, ci) => `<td style="${ci === 0 ? '' : 'text-align:right'}${note ? ';border-bottom:none' : ''}">${escapeHtml(c)}</td>`)
        .join('')}</tr>${noteHtml}`;
    })
    .join('');
  const totalsHtml = (data.totals || [])
    .map(
      (t) => `
      <div style="display:flex;justify-content:space-between;margin:2px 0;${t.bold ? 'font-weight:700;' : ''}${
        t.danger ? 'color:#c0392b;' : ''
      }">
        <span>${escapeHtml(t.label)}</span><span>${escapeHtml(t.value)}</span>
      </div>`
    )
    .join('');
  w.document.write(`<!DOCTYPE html><html><head><meta charset="utf-8"><title>${escapeHtml(data.title)}</title>
    <style>
      body{font-family: Arial, sans-serif; padding:16px; font-size:13px; color:#111;}
      h2{margin:0 0 4px 0; font-size:18px; text-align:center;}
      .sub{color:#555; font-size:12px; margin-bottom:4px; text-align:center;}
      table{width:100%; border-collapse:collapse; margin:12px 0 10px;}
      th,td{text-align:left; padding:4px 2px; border-bottom:1px solid #eee; font-size:12px;}
      .totals{border-top:1px solid #333; padding-top:6px; margin-top:6px;}
      .footer{margin-top:14px; font-size:11px; color:#777; text-align:center;}
    </style></head><body>
      <h2>${escapeHtml(data.title)}</h2>
      ${(data.subtitleLines || []).map((l) => `<div class="sub">${escapeHtml(l)}</div>`).join('')}
      ${
        (data.columns || []).length
          ? `<table><thead><tr>${(data.columns || [])
              .map((c, i) => `<th style="${i === 0 ? '' : 'text-align:right'}">${escapeHtml(c)}</th>`)
              .join('')}</tr></thead><tbody>${rowsHtml}</tbody></table>`
          : ''
      }
      <div class="totals">${totalsHtml}</div>
      ${(data.footerLines || []).map((l) => `<div class="footer">${escapeHtml(l)}</div>`).join('')}
      <script>window.onload = function() { window.print(); };</script>
    </body></html>`);
  w.document.close();
}

export async function downloadReceiptPdf(data, filename) {
  let JsPdf;
  try {
    JsPdf = await loadJsPdf();
  } catch (e) {
    alert(e.message || "PDF yuklab bo'lmadi");
    return;
  }

  const pageWidth = 300;
  const margin = 18;
  const lineHeight = 14;
  const rows = data.rows || [];
  const rowNotes = data.rowNotes || [];
  const noteLineHeight = 11;
  const totals = data.totals || [];
  const subtitleLines = data.subtitleLines || [];
  const footerLines = data.footerLines || [];
  const hasTable = (data.columns || []).length > 0;
  const noteCount = rowNotes.filter(Boolean).length;

  const estimatedHeight =
    margin * 2 +
    22 + // title
    subtitleLines.length * (lineHeight - 3) +
    10 +
    (hasTable ? lineHeight + 10 + rows.length * lineHeight + noteCount * noteLineHeight + 16 : 0) +
    totals.length * lineHeight +
    10 +
    footerLines.length * (lineHeight - 4) +
    10;

  // MUHIM: format massividagi balandlik ENIDAN kichik bo'lib qolsa, jsPDF
  // buni "landscape" deb hisoblab, portret rejimini majburlash uchun
  // eni/balandligini ICHKARIDA almashtirib yuboradi — natijada barcha x
  // koordinatalarimiz (masalan rightX = pageWidth - margin) haqiqiy
  // sahifadan tashqariga chiqib, matn ko'rinmay/kesilib qolardi (aynan shu
  // sabab tufayli sinovda summalar chek qog'ozidan "chala" chiqqan edi).
  // Shuning uchun balandlik hech qachon endan kichik bo'lmasligi SHART.
  const doc = new JsPdf({ unit: 'pt', format: [pageWidth, Math.max(pageWidth, estimatedHeight)], orientation: 'portrait' });
  registerPdfFonts(doc);
  let y = margin;
  const leftX = margin;
  const rightX = pageWidth - margin;
  const centerX = pageWidth / 2;

  // (40) MUHIM: jsPDF'ning o'rnatilgan {align:'right'}/{align:'center'}
  // parametri, sinovda, uzun raqamli matnlarni sahifa chetidan tashqariga
  // chiqarib, kesib qo'yishi kuzatildi (haqiqiy brauzerda test qilinganda
  // topilgan xato). Shuning uchun matn kengligini o'zimiz hisoblab, chapdan
  // boshlanadigan (default) text() bilan qo'lda joylashtiramiz — bu har
  // doim ishonchli natija beradi.
  function textRight(text, x, yPos) {
    const w = doc.getTextWidth(text);
    doc.text(text, x - w, yPos);
  }
  function textCenter(text, x, yPos) {
    const w = doc.getTextWidth(text);
    doc.text(text, x - w / 2, yPos);
  }

  doc.setFont('DejaVuSans', 'bold');
  doc.setFontSize(13);
  textCenter(String(data.title || ''), centerX, y);
  y += 18;

  doc.setFont('DejaVuSans', 'normal');
  doc.setFontSize(9);
  for (const line of subtitleLines) {
    textCenter(String(line), centerX, y);
    y += lineHeight - 3;
  }
  y += 6;

  if (hasTable) {
    doc.setFont('DejaVuSans', 'bold');
    doc.setFontSize(9);
    doc.text(String(data.columns[0]), leftX, y);
    textRight(String(data.columns[data.columns.length - 1]), rightX, y);
    y += 10;
    doc.setLineWidth(0.5);
    doc.line(leftX, y, rightX, y);
    y += 10;

    doc.setFont('DejaVuSans', 'normal');
    doc.setFontSize(9);
    rows.forEach((r, i) => {
      const name = String(r[0] ?? '');
      const last = String(r[r.length - 1] ?? '');
      const mid = r.slice(1, -1).join('  x  ');
      const valueText = mid ? `${mid} = ${last}` : last;
      // Nomi juda uzun bo'lsa, summaga joy qoldirish uchun qisqartiramiz.
      const maxNameWidth = pageWidth - margin * 2 - doc.getTextWidth(valueText) - 10;
      let displayName = name;
      while (doc.getTextWidth(displayName) > maxNameWidth && displayName.length > 1) {
        displayName = displayName.slice(0, -1);
      }
      if (displayName !== name) displayName = displayName.slice(0, -1) + '…';
      doc.text(displayName, leftX, y);
      textRight(valueText, rightX, y);
      y += lineHeight;
      // (37) Kafolat izohi — faqat shu qatorda belgilangan bo'lsa chiqadi.
      const note = rowNotes[i];
      if (note) {
        doc.setFont('DejaVuSans', 'normal');
        doc.setFontSize(7.5);
        doc.setTextColor(0, 51, 160);
        doc.text('🛡 ' + String(note), leftX, y - 3);
        doc.setTextColor(0, 0, 0);
        doc.setFontSize(9);
        y += noteLineHeight - 3;
      }
    });
    y += 4;
    doc.line(leftX, y, rightX, y);
    y += 12;
  }

  doc.setFontSize(10);
  for (const t of totals) {
    doc.setFont('DejaVuSans', t.bold ? 'bold' : 'normal');
    doc.text(String(t.label), leftX, y);
    textRight(String(t.value), rightX, y);
    y += lineHeight;
  }

  if (footerLines.length) {
    y += 8;
    doc.setFont('DejaVuSans', 'normal');
    doc.setFontSize(8);
    for (const line of footerLines) {
      textCenter(String(line), centerX, y);
      y += lineHeight - 4;
    }
  }

  doc.save(filename || 'chek.pdf');
}

// Bitta sotuv (chek) uchun receipt.js formatiga mos ma'lumot tayyorlaydi.
export function buildSaleReceiptData(sale, items, { customerName, sellerName } = {}) {
  const subtitleLines = [new Date(sale.created_at).toLocaleString('uz-UZ')];
  if (customerName) subtitleLines.push(`Mijoz: ${customerName}`);
  if (sellerName) subtitleLines.push(`Sotuvchi: ${sellerName}`);

  const rows = (items || []).map((it) => [it.product_name, String(it.quantity), money(it.total_price ?? it.unit_price * it.quantity)]);
  // (37) Kafolat — faqat kafolat kuni belgilangan qatorlarga alohida izoh
  // qo'shiladi (bilingual O'zbek/Rus); qolgan qatorlarga hech narsa
  // qo'shilmaydi (ular kafolatsiz ekani shunchaki ko'rinib turadi).
  const rowNotes = (items || []).map((it) => {
    const days = Math.round(Number(it.warranty_days) || 0);
    return days > 0 ? `Kafolat: ${days} kun / Гарантия: ${days} дней` : null;
  });

  const totals = [];
  totals.push({ label: 'Oraliq summa', value: money(sale.subtotal_amount) });
  if (Number(sale.discount_amount) > 0) totals.push({ label: 'Chegirma', value: '-' + money(sale.discount_amount), danger: true });
  totals.push({ label: 'Jami', value: money(sale.total_amount), bold: true });
  if (Number(sale.paid_naqd) > 0) totals.push({ label: "Naqd to'langan", value: money(sale.paid_naqd) });
  if (Number(sale.paid_karta) > 0) totals.push({ label: "Karta to'langan", value: money(sale.paid_karta) });
  const debtRemaining = Number(sale.debt_remaining ?? sale.debt_amount ?? 0);
  if (debtRemaining > 0) totals.push({ label: "Qarz qoldig'i", value: money(debtRemaining), danger: true });

  return {
    title: `Chek #${sale.id ?? ''}`,
    subtitleLines,
    columns: ['Mahsulot', 'Miqdor', 'Summa'],
    rows,
    rowNotes,
    totals,
    footerLines: ['Xaridingiz uchun rahmat!'],
  };
}

// Bitta kirim hujjati uchun receipt.js formatiga mos ma'lumot tayyorlaydi.
export function buildKirimReceiptData(doc) {
  const subtitleLines = [`Ta'minotchi: ${doc.supplier_name || ''}`, new Date(doc.date || doc.created_at).toLocaleDateString('uz-UZ')];
  if (doc.note) subtitleLines.push(`Izoh: ${doc.note}`);

  const rows = (doc.items || []).map((it) => [
    it.product_name || 'Eski qarz',
    it.quantity != null ? String(it.quantity) : '-',
    money(it.amount),
  ]);

  return {
    title: 'Kirim hujjati',
    subtitleLines,
    columns: ['Mahsulot', 'Soni', 'Summa'],
    rows,
    totals: [{ label: 'Jami', value: money(doc.total), bold: true }],
  };
}

// (6) Narx yorlig'i (shtrix-kod chop etish) — mahsulot nomi, narxi va
// SKANERLANADIGAN Code128 shtrix-kod tasviri bilan kichik yorliq. Yorliq
// printerlarida ham, oddiy A4 qog'ozda chop etib qaychi bilan kesib olishda
// ham ishlatish mumkin bo'lgan taxminiy o'lcham tanlangan.
export function buildBarcodeLabelData(product) {
  return {
    name: product.name,
    price: money(product.sale_price),
    barcode: product.barcode || '',
  };
}

// Shtrix-kodni SVG sifatida joriy oyna kontekstida chizib, tayyor SVG
// matnini qaytaradi — shunda popup/PDF ichida JsBarcode'ni qayta yuklash
// yoki alohida oynada ishga tushirish shart bo'lmaydi.
async function renderBarcodeSvgString(code) {
  const JsBarcodeFn = await loadJsBarcode();
  const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  JsBarcodeFn(svg, code, { format: 'CODE128', displayValue: true, fontSize: 14, height: 40, margin: 4 });
  return new XMLSerializer().serializeToString(svg);
}

export async function printBarcodeLabel(data) {
  if (!data.barcode) {
    alert("Bu mahsulotda shtrix-kod yo'q");
    return;
  }
  let svgString;
  try {
    svgString = await renderBarcodeSvgString(data.barcode);
  } catch (e) {
    alert(e.message || "Shtrix-kodni chizib bo'lmadi");
    return;
  }
  const w = window.open('', '_blank', 'width=380,height=300');
  if (!w) {
    alert("Chop etish oynasini ochib bo'lmadi — brauzeringiz popup oynalarni bloklagan bo'lishi mumkin.");
    return;
  }
  w.document.write(`<!DOCTYPE html><html><head><meta charset="utf-8"><title>Narx yorlig'i</title>
    <style>
      body{font-family: Arial, sans-serif; margin:0; padding:10px; text-align:center;}
      .label{ display:inline-block; border:1px dashed #999; padding:8px 12px; }
      .name{ font-size:13px; font-weight:700; margin-bottom:2px; max-width:220px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
      .price{ font-size:15px; font-weight:800; margin-bottom:4px; }
      svg{ display:block; margin:0 auto; }
    </style></head><body>
      <div class="label">
        <div class="name">${escapeHtml(data.name)}</div>
        <div class="price">${escapeHtml(data.price)}</div>
        ${svgString}
      </div>
      <script>window.onload = function() { window.print(); };</script>
    </body></html>`);
  w.document.close();
}

export async function downloadBarcodeLabelPdf(data, filename) {
  if (!data.barcode) {
    alert("Bu mahsulotda shtrix-kod yo'q");
    return;
  }
  let JsPdf;
  let JsBarcodeFn;
  try {
    [JsPdf, JsBarcodeFn] = await Promise.all([loadJsPdf(), loadJsBarcode()]);
  } catch (e) {
    alert(e.message || "Yorliqni yuklab bo'lmadi");
    return;
  }

  // Shtrix-kodni avval alohida canvas'ga chizamiz, so'ng PDF'ga tayyor
  // rasm sifatida joylashtiramiz (jsPDF o'zi shtrix-kod chizmaydi).
  const canvas = document.createElement('canvas');
  JsBarcodeFn(canvas, data.barcode, { format: 'CODE128', displayValue: true, fontSize: 16, height: 50, margin: 6 });
  const imgData = canvas.toDataURL('image/png');

  const pageWidth = 180; // ~63mm — yorliq printerlar uchun taxminiy o'lcham
  const pageHeight = 110; // ~39mm
  const doc = new JsPdf({ unit: 'pt', format: [pageWidth, pageHeight], orientation: 'landscape' }); // yorliq KENG (landscape) shaklda — pageWidth > pageHeight bo'lgani uchun jsPDF'ga buni portret emas, LANDSCAPE ekanini aniq aytish kerak, aks holda ichkarida eni/balandligi almashtirilib, matn sahifadan chiqib ketadi (xuddi chekdagi avvalgi xato kabi).
  registerPdfFonts(doc);

  const centerX = pageWidth / 2;
  function textCenter(text, x, yPos, size, bold) {
    doc.setFont('DejaVuSans', bold ? 'bold' : 'normal');
    doc.setFontSize(size);
    const w = doc.getTextWidth(text);
    doc.text(text, x - w / 2, yPos);
  }

  textCenter(String(data.name || ''), centerX, 16, 10, true);
  textCenter(String(data.price || ''), centerX, 30, 11, true);

  const imgRatio = canvas.width / canvas.height;
  const imgH = 48;
  const imgW = Math.min(pageWidth - 16, imgH * imgRatio);
  doc.addImage(imgData, 'PNG', centerX - imgW / 2, 38, imgW, imgH);

  doc.save(filename || 'yorliq.pdf');
}
